actions.command:
python3 -c "import os, re, textwrap, pathlib; target=pathlib.Path(os.environ['TARGET_DIR'])/'run_buggy.py'; lines=target.read_text().splitlines(); out=[]; meta_added=False; 
for line in lines:
    out.append(line)
    if not meta_added and re.search(r'^\s*ids\s*=\s*\[', line):
        indent=re.match(r'^(\s*)', line).group(1)
        block=textwrap.dedent('''\n# ENHANCED_PROGRAM_V1: Add per-document metadata for retrieval\nmetadatas = [\n    {\n        \"source\": pdf_file.filename,\n        \"user\": str(user_id),\n        \"created_at\": now.strftime(\"%d/%m/%Y %H:%M:%S\")\n    }\n    for _ in documents\n]\n''')
        for b in block.splitlines():
            out.append(indent + b)
        meta_added=True
        continue
    if 'collection_metadata' in line:
        new_line=re.sub(r',\\s*collection_metadata\\s*=\\s*\\{[^}]*\\}', '', line)
        if 'metadatas=' not in new_line:
            new_line=re.sub(r'\\)\\s*$', ', metadatas=metadatas)', new_line)
        out[-1]=new_line
target.write_text('\\n'.join(out) + '\\n')"

